"use client";

/**
 * Due-date control that flags overdue values.
 */
import { DatePicker } from "@/components/ui/date-picker";
import { toIsoTimestamp } from "@/types/common";
import { isOverdue } from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
};

/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(value: IsoTimestamp | null): string | null {
  return value === null ? null : value.slice(0, 10);
}

export function fromDateInputValue(value: string | null): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  // End of day: an issue due "today" is not overdue at 09:00.
  return toIsoTimestamp(new Date(`${value}T23:59:59.999Z`));
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const overdue = isOverdue(props.value);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value)}
        placeholder="No due date"
        onChange={(value) => props.onChange(fromDateInputValue(value))}
      />
      {overdue ? (
        <p className="text-xs text-red-600">This issue is past its due date.</p>
      ) : null}
    </div>
  );
}
"use client";

/**
 * The per-request tenant context the dashboard layout installs.
 *
 * Everything below `[orgSlug]` needs the same three values — the organization,
 * the resolved `Actor` and the evaluated flag snapshot — plus the quota checks
 * the billing service already computed for the shell. Passing those down by
 * props through every component would be noise, so the layout renders one
 * `OrgProvider` and `useOrg()` / `usePermission()` / `usePlanLimits()` read it.
 */
import { createContext, type ReactElement, type ReactNode } from "react";
import type { LimitCheck } from "@/types/billing";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

export interface OrgContextValue {
  readonly org: Organization;
  readonly actor: Actor;
  readonly flags: FeatureFlagSnapshot;
  /** Quota checks for the current billing period, or `[]` when not loaded. */
  readonly limitChecks: readonly LimitCheck[];
}

export const OrgContext = createContext<OrgContextValue | null>(null);

export interface OrgProviderProps {
  readonly value: OrgContextValue;
  readonly children?: ReactNode;
}

export function OrgProvider(props: OrgProviderProps): ReactElement {
  return (
    <OrgContext.Provider value={props.value}>
      {props.children}
    </OrgContext.Provider>
  );
}
"use client";

/**
 * Reads the org/actor/flag context installed by the dashboard layout.
 */
import { useContext } from "react";
import { OrgContext, type OrgContextValue } from "./org-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Throws rather than returning a half-built tenant context — a client
 *  component rendered outside `[orgSlug]` is a routing bug, not a state. */
export function useOrgContext(): OrgContextValue {
  const value = useContext(OrgContext);
  if (value === null) {
    throw new Error(
      "useOrg() must be rendered inside the dashboard <OrgProvider>.",
    );
  }
  return value;
}

export function useOrg(): {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
} {
  const { org, actor, flags } = useOrgContext();
  return { org, actor, flags };
}

