}

/** The `YYYY-MM-DD` calendar date of an instant on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return formatLocalDate(wallClock(parseIso(value).getTime(), timeZone));
}

/**
 * The UTC instant at which the zone's calendar day containing `reference`
 * began. Usually local midnight; when a daylight-saving jump swallows
 * midnight it is the first instant of that date.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const { year, month, day } = wallClock(reference.getTime(), timeZone);
  return toIsoTimestamp(new Date(instantAtLocal(year, month, day, 0, timeZone)));
}

/**
 * The UTC instant at which local midnight fell on the calendar date that lies
 * `days` calendar days before today's date on the zone's clock. Counting in
 * calendar days (not 24-hour blocks) keeps the answer on a midnight across
 * daylight-saving changes.
 */
export function startOfLocalDayBefore(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const today = wallClock(reference.getTime(), timeZone);
  const { year, month, day } = shiftDate(today, -days);
  return toIsoTimestamp(new Date(instantAtLocal(year, month, day, 0, timeZone)));
}

/** The hour (0-23) the zone's clock shows at `reference`. */
export function localHour(reference: Date, timeZone: string): number {
  return wallClock(reference.getTime(), timeZone).hour;
}

/**
 * True once the calendar day (on the workspace's clock) that contains `dueAt`
 * has ended. Due dates are whole days: on the due day itself nothing is
 * overdue yet, whatever time of day `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const due = formatLocalDate(wallClock(parseIso(dueAt).getTime(), timeZone));
  const today = formatLocalDate(wallClock(reference.getTime(), timeZone));
  return due < today;
}

