s=s.replace(old,new)

# digestWindow
old=s[s.index("/**\n * The 24-hour window a digest covers"):]
new='''/**
 * The window a digest covers. It ends at the most recent `digestHour`:00 on the
 * workspace's clock at or before `reference` — today's once it has passed,
 * yesterday's otherwise, so a job run early never mails an empty digest and
 * then skips the real one — and starts at the same local hour on the previous
 * calendar day. Across a daylight-saving change that is 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  let endDate: LocalDate = wallClock(reference.getTime(), timeZone);
  let end = instantAtLocal(endDate.year, endDate.month, endDate.day, digestHour, timeZone);
  if (end > reference.getTime()) {
    endDate = shiftDate(endDate, -1);
    end = instantAtLocal(endDate.year, endDate.month, endDate.day, digestHour, timeZone);
  }

  const startDate = shiftDate(endDate, -1);
  const start = instantAtLocal(
    startDate.year,
    startDate.month,
    startDate.day,
    digestHour,
    timeZone,
  );

  return { start: toIsoTimestamp(new Date(start)), end: toIsoTimestamp(new Date(end)) };
}

type LocalDate = { year: number; month: number; day: number };
type WallClock = LocalDate & { hour: number; minute: number; second: number };

const zoneFormatters = new Map<string, Intl.DateTimeFormat>();

/** Throws `RangeError` for a zone `Intl` does not recognise. */
function zoneFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = zoneFormatters.get(timeZone);
  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      calendar: "gregory",
      numberingSystem: "latn",
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    zoneFormatters.set(timeZone, formatter);
  }
  return formatter;
}

/** What the zone's clock and calendar read at the instant `epochMs`. */
function wallClock(epochMs: number, timeZone: string): WallClock {
  const fields: Record<string, number> = {};
  for (const part of zoneFormatter(timeZone).formatToParts(new Date(epochMs))) {
    if (part.type !== "literal") fields[part.type] = Number(part.value);
  }
  return {
    year: fields.year ?? Number.NaN,
    month: fields.month ?? Number.NaN,
    day: fields.day ?? Number.NaN,
    hour: (fields.hour ?? Number.NaN) % 24,
    minute: fields.minute ?? Number.NaN,
    second: fields.second ?? Number.NaN,
  };
}

function formatLocalDate({ year, month, day }: LocalDate): string {
  const pad = (value: number, width: number): string =>
    String(value).padStart(width, "0");
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

/** Calendar arithmetic on a date: unaffected by the length of any day. */
function shiftDate(date: LocalDate, days: number): LocalDate {
  const shifted = new Date(Date.UTC(date.year, date.month - 1, date.day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

/** A wall-clock reading expressed as if it were UTC. */
function asUtcMs(clock: WallClock): number {
  return Date.UTC(
    clock.year,
    clock.month - 1,
    clock.day,
    clock.hour,
    clock.minute,
    clock.second,
  );
}

/** The zone's offset from UTC, in ms, at the instant `epochMs`. */
function zoneOffsetMs(epochMs: number, timeZone: string): number {
  const whole = Math.floor(epochMs / 1000) * 1000;
  return asUtcMs(wallClock(whole, timeZone)) - whole;
}

/**
 * The instant at which the zone's clock first reads `hour:00` on the given
 * calendar date. When the reading occurs twice (the clock was set back) that
 * is the earlier instant; when it never occurs (the clock jumped forward over
 * it) it is the instant the jump lands on, i.e. the reading shifted by the
 * length of the gap.
 */
function instantAtLocal(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number {
  const wanted = Date.UTC(year, month - 1, day, hour, 0, 0);

  // The zone's offset just before and just after any change near `wanted`.
  const before = zoneOffsetMs(wanted - DAY_MS, timeZone);
  const after = zoneOffsetMs(wanted + DAY_MS, timeZone);

  const valid = [...new Set([before, after])]
    .map((offset) => wanted - offset)
    .filter((instant) => asUtcMs(wallClock(instant, timeZone)) === wanted);

  if (valid.length > 0) return Math.min(...valid);
  return wanted - before;
}
