    expect(isOverdue(null, REFERENCE)).toBe(false);
  });

  it("is not overdue on the due day itself, whatever time of day it names", () => {
    expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T23:59:59.999Z"), REFERENCE)).toBe(false);
  });

  it("becomes overdue the moment the due day has ended", () => {
    const due = iso("2026-03-15T09:00:00.000Z");
    expect(isOverdue(due, new Date("2026-03-15T23:59:59.999Z"))).toBe(false);
    expect(isOverdue(due, new Date("2026-03-16T00:00:00.000Z"))).toBe(true);
    expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  });

  it("reads the due day on the workspace clock", () => {
    // 2026-03-15T20:00Z is already the 16th in Tokyo (UTC+9).
    const due = iso("2026-03-15T20:00:00.000Z");
    expect(isOverdue(due, new Date("2026-03-16T14:59:59.000Z"), "Asia/Tokyo")).toBe(false);
    expect(isOverdue(due, new Date("2026-03-16T15:00:00.000Z"), "Asia/Tokyo")).toBe(true);
    // The same instants on a UTC clock: the 15th ends at 2026-03-16T00:00Z.
    expect(isOverdue(due, new Date("2026-03-16T14:59:59.000Z"))).toBe(true);
  });

  it("gives a calendar date on the zone's clock", () => {
    const stamp = iso("2026-03-15T23:30:00.000Z");
    expect(localDate(stamp, "UTC")).toBe("2026-03-15");
    expect(localDate(stamp, "Asia/Tokyo")).toBe("2026-03-16");
    expect(localDate(stamp, "America/Los_Angeles")).toBe("2026-03-15");
    expect(localDate(iso("2026-03-15T03:30:00.000Z"), "America/Los_Angeles")).toBe("2026-03-14");
  });

  it("refuses a zone Intl does not know", () => {
    expect(() => localDate(iso("2026-03-15T00:00:00.000Z"), "Mars/Olympus")).toThrow(RangeError);
  });

  it("finds the instant a local day began", () => {
