/** Workspace settings: the time zone is an IANA name that Intl recognises. */
import { describe, expect, it } from "vitest";
import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";
import { ORG_A } from "../helpers/factories";

describe("schemas/organization", () => {
  it("defaults the time zone to UTC", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
  });

  it("accepts an IANA zone name", () => {
    const parsed = organizationSettingsSchema.parse({ timeZone: "Asia/Tokyo" });
    expect(parsed.timeZone).toBe("Asia/Tokyo");
  });

  it("rejects a zone Intl does not recognise", () => {
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(false);
    expect(organizationSettingsSchema.safeParse({ timeZone: "" }).success).toBe(false);
    expect(
      updateOrganizationSchema.safeParse({
        orgId: ORG_A,
        settings: { timeZone: "Not/AZone" },
      }).success,
    ).toBe(false);
  });

  it("does not fill in settings the caller left out of a patch", () => {
    const parsed = updateOrganizationSchema.parse({
      orgId: ORG_A,
      settings: { digestHourUtc: 9 },
    });
    expect(parsed.settings).toEqual({ digestHourUtc: 9 });
  });
});
