import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function makeTenant(slug: string, timeZone: string): Promise<Tenant> {
  // The free plan keeps 30 days of history.
  const tenant = await createTenant(slug, "free");
  await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone } });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function recordAt(tenant: Tenant, occurredAt: string): Promise<void> {
  await activityRepo.insertActivity({
    orgId: tenant.org.id,
    action: "issue.created",
    actorId: null,
    subjectKind: "issue",
    subjectId: occurredAt,
    projectId: null,
    summary: occurredAt,
    metadata: {},
    occurredAt: occurredAt as IsoTimestamp,
  });
}

async function remaining(tenant: Tenant): Promise<string[]> {
  const page = await activityRepo.listActivity({
    orgId: tenant.org.id,
    limit: 100,
    cursor: null,
  });
  return page.items.map((event) => event.summary).sort();
}

describe("jobs/cleanup-archived-job cut-off", () => {
  const NOW = new Date("2026-03-15T12:00:00.000Z");

  it("cuts at UTC midnight 30 calendar days back for a UTC workspace", async () => {
    const tenant = await makeTenant("cleanup-utc", "UTC");
